:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-surface: #fbfbfb;
  --color-mist-panel: #f4f5f6;
  --color-jet-ink: #101112;
  --color-graphite-ink: #242629;
  --color-iron-body: #505155;
  --color-slate-caption: #75777c;
  --color-pewter-muted: #9fa1a7;
  --color-ash-hairline: #0000000d;
  --color-dove-border: #e6e7ea;
  --color-signal-blue: #266df0;
  --color-signal-wash: #e5eeff;
  --color-mint-chip: #e0fced;

  /* Typography — Font Families */
  --font-inter-display: "Inter Display", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-tiempos-text: "Tiempos Text", "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.5;
  --tracking-small: -0.16px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: -0.16px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.385;
  --tracking-body-sm: -0.13px;
  --text-body: 14px;
  --leading-body: 1.429;
  --tracking-body: -0.14px;
  --text-body-lg: 15px;
  --leading-body-lg: 1.333;
  --tracking-body-lg: -0.15px;
  --text-subheading: 24px;
  --leading-subheading: 1.15;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.15;
  --tracking-heading-sm: -0.8px;
  --text-heading: 40px;
  --leading-heading: 1.1;
  --tracking-heading: -0.4px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1.083;
  --tracking-heading-lg: -0.72px;
  --text-display: 68px;
  --leading-display: 1.05;
  --tracking-display: -1.36px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-13: 13px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-44: 44px;
  --spacing-48: 48px;
  --spacing-112: 112px;
  --spacing-152: 152px;

  /* Layout */
  --layout-max-width: 1440px;
  --layout-section-gap: 112px;
  --layout-card-padding: 32px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-md-2: 7px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 12px;
  --radius-3xl: 16px;
  --radius-3xl-2: 23px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 12px;
  --radius-buttons: 10px;
  --radius-inputs: 10px;
  --radius-nav: 12px;
  --radius-inner-tiles: 8px;
  --radius-images: 7px;
  --radius-tags: 6px;
  --radius-badges: 6px;
  --radius-small-elements: 4px;
  --radius-alert-banners: 16px;
  --radius-sections: 23px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 1px 3px 0px rgba(0, 0, 0, 0.04), 0px 0px 2px 0px rgba(28, 40, 64, 0.18);
  --shadow-subtle-2: inset 0px 0px 0px 1px rgb(238, 239, 241);
  --shadow-sm: inset 0.2px 0.2px 2px 0px rgba(255, 255, 255, 0.1), 0px 1.5px 1.5px 0px rgba(0, 0, 0, 0.25);
  --shadow-sm-2: 0px 2px 4px -2px rgba(15, 107, 233, 0.12), 0px 3px 6px -2px rgba(15, 107, 233, 0.08);
  --shadow-md: 0px 0px 1px 1px rgba(0, 22, 62, 0.01), 0px 4px 12px -1px rgba(0, 22, 62, 0.04), 0px 1px 3px -1px rgba(0, 22, 62, 0.18);
  --shadow-lg: 0px 0px 0px 1px rgba(11, 13, 24, 0.06), 0px 1px 2px 0px rgba(11, 13, 24, 0.024), 0px 3px 6px 0px rgba(11, 13, 24, 0.03), 0px 8px 14px 0px rgba(11, 13, 24, 0.035), 0px 16px 28px 0px rgba(11, 13, 24, 0.04);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-surface: #fbfbfb;
  --surface-mist-panel: #f4f5f6;
  --surface-paper-raised: #ffffff;
  --surface-jet-ink: #101112;
}

